#[path="../owner_registry.rs"]mod owner_registry;#[path="../owner_budget.rs"]mod owner_budget;#[path="../journal.rs"]mod journal;#[path="../owner.rs"]mod owner;#[path="../face_owner.rs"]mod face_owner;
use std::alloc::{GlobalAlloc,Layout,System};use std::sync::atomic::{AtomicBool,AtomicUsize,Ordering};use glam::DVec3;use ingetrazo_core::mesh::Mesh;
static TRACK:AtomicBool=AtomicBool::new(false);static MAX:AtomicUsize=AtomicUsize::new(0);static BYTES:AtomicUsize=AtomicUsize::new(0);static CALLS:AtomicUsize=AtomicUsize::new(0);fn observe(n:usize){if TRACK.load(Ordering::Relaxed){MAX.fetch_max(n,Ordering::Relaxed);BYTES.fetch_add(n,Ordering::Relaxed);CALLS.fetch_add(1,Ordering::Relaxed);}}
static FAIL:AtomicBool=AtomicBool::new(false);struct Fault;unsafe impl GlobalAlloc for Fault{unsafe fn alloc(&self,l:Layout)->*mut u8{observe(l.size());if l.size()==3*std::mem::size_of::<Vec<usize>>()&&FAIL.swap(false,Ordering::SeqCst){std::ptr::null_mut()}else{System.alloc(l)}}unsafe fn dealloc(&self,p:*mut u8,l:Layout){System.dealloc(p,l)}unsafe fn realloc(&self,p:*mut u8,l:Layout,n:usize)->*mut u8{{observe(n);System.realloc(p,l,n)}}}#[global_allocator]static ALLOC:Fault=Fault;
fn triangle(o:&face_owner::FaceOwner)->face_owner::FaceTransaction{let mut t=o.begin().unwrap();t.add_face(&[DVec3::ZERO,DVec3::X,DVec3::Y],&[]).unwrap();let mut a=std::collections::HashMap::new();a.insert("vendor".into(),serde_json::json!({"nested":[null,true,"payload".repeat(8192)]}));a.insert("layer".into(),serde_json::json!("Authored"));t.set_face_attributes(0,a).unwrap();t}
fn pointer(m:&Mesh)->*const u8{m.faces[0].attrs["vendor"]["nested"][2].as_str().unwrap().as_ptr()}
fn main(){let mut o=face_owner::FaceOwner::new(Mesh::new()).unwrap();let t=triangle(&o);o.commit(t).unwrap();let ptr=pointer(o.mesh());TRACK.store(true,Ordering::SeqCst);o.undo().unwrap();o.redo().unwrap();TRACK.store(false,Ordering::SeqCst);assert_eq!(pointer(o.mesh()),ptr);assert!(MAX.load(Ordering::SeqCst)<8192*7,"attribute-sized allocation during history");let max=MAX.load(Ordering::SeqCst);let bytes=BYTES.load(Ordering::SeqCst);let calls=CALLS.load(Ordering::SeqCst);o.undo().unwrap();let saved=o.mesh().clone();let budget=o.budget();let before=budget.snapshot();let mut earlier=o.begin().unwrap();let candidate=triangle(&o);FAIL.store(true,Ordering::SeqCst);let error=o.commit(candidate).unwrap_err();assert_eq!(error,"New radial records refused");assert!(!FAIL.load(Ordering::SeqCst));assert_eq!(o.mesh(),&saved);assert_eq!(o.history_counts(),(0,1));assert_eq!(budget.snapshot().history,before.history);earlier.add_face(&[DVec3::ZERO,DVec3::X,DVec3::Y],&[]).unwrap();o.commit(earlier).unwrap();assert_eq!(o.history_counts(),(1,0));o.undo().unwrap();o.redo().unwrap();drop(o);assert_eq!(budget.snapshot().total(),0);println!("{{\"payload_bytes\":57344,\"history_max_allocation\":{max},\"history_total_allocation_bytes\":{bytes},\"history_allocation_calls\":{calls},\"pointer_stable\":true,\"actual_refusal_preserved_redo\":true,\"ledger_released\":true}}");println!("actual new-radial allocator refusal preserves mesh, Redo, earlier transaction; retry+Undo/Redo and ledger release PASS");}
